'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state = {done:[],font:false,lastLesson:null};
let storageOK = true;
try {const saved = JSON.parse(localStorage.getItem('ai-classroom-v1') || '{}'); state.done = Array.isArray(saved.done) ? [...new Set(saved.done.filter(x => Number.isInteger(x) && x >= 0 && x < LESSONS.length))] : []; state.font = saved.font === true;state.lastLesson=Number.isInteger(saved.lastLesson)&&LESSONS[saved.lastLesson]?saved.lastLesson:null;} catch {storageOK = false;}
function save() {try {localStorage.setItem('ai-classroom-v1', JSON.stringify(state));} catch {storageOK = false; toast('浏览器未允许保存进度，本次仍可正常学习。');}}
const nav = [['home','⌂','学习首页'],['trust','◎','怎样放心用 AI'],['courses','▤','全部课程'],['scenes','▦','案例演示'],['students','◇','大学生专区'],['tools','✧','提问工具箱'],['stocks','▥','股票研究'],['help','?','看不懂？问 AI'],['about','◇','网站制作过程']];
const main = $('#main');
const menuButton=$('#menu-toggle');
function closeMenu(){document.body.classList.remove('menu-open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='打开目录';}
menuButton.onclick=()=>{const open=document.body.classList.toggle('menu-open');menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'收起目录':'打开目录';};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();menuButton.focus();}});
$('#navigation').addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});
$('.skip').addEventListener('click',event=>{event.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({block:'start'});});
let currentLesson = null;
let toastTimer;
function toast(text) {$('#toast').textContent = text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer = setTimeout(() => $('#toast').classList.remove('visible'),3500);}
function applyFont(){document.documentElement.classList.toggle('large-text',state.font);$('#font-toggle').setAttribute('aria-pressed',String(state.font));$('#font-toggle').textContent=state.font?'恢复字号':'大字模式';}
applyFont();
$('#font-toggle').onclick=()=>{state.font=!state.font;applyFont();save();};
$('#print').onclick=()=>window.print();
function heading(kicker,title,description){return `<div class="page-heading"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>`;}
function button(text,href,cls=''){return `<a class="btn ${cls}" href="${href}">${text}</a>`;}
function template(text,label='可以直接复制给 AI'){return `<div class="template"><div class="template-label">${label}</div><pre>${esc(text)}</pre><button class="btn secondary" data-copy-parent>复制这段提问</button></div>`;}
function courseCard(l,i){return `<a href="#lesson/${i}" class="card course-card"><div class="course-top"><span class="course-symbol ${l.color}">${l.icon}</span><span class="course-number">第 ${String(COURSE_ORDER.indexOf(i)+1).padStart(2,'0')} 课</span></div><h3>${l.title}</h3><p>${l.desc}</p><div class="course-bottom"><span>${l.time} 分钟 · ${l.tag}</span><span class="state">${state.done.includes(i)?'✓ 已学完':'开始学习'}</span></div></a>`;}
function home(){return trustHome();}
function resumeLesson(){if(state.lastLesson===null)return '';const i=state.lastLesson;return '<div class="resume-learning"><div><span>上次看到这里</span><strong>第 '+(COURSE_ORDER.indexOf(i)+1)+' 课 · '+esc(LESSONS[i].title)+'</strong><small>已学完 '+state.done.length+' / '+LESSONS.length+' 课</small></div>'+button('继续学习','#lesson/'+i,'secondary')+'</div>';}
function lessonOutline(l){return '<details class="lesson-outline"><summary>本课内容 · '+l.sections.length+' 个小节和一组练习</summary><div>'+l.sections.map(([title],n)=>'<button type="button" data-jump="lesson-section-'+n+'">'+esc(title)+'</button>').join('')+'<button type="button" data-jump="lesson-practice">动手练习</button><button type="button" data-jump="lesson-quiz">随堂题</button></div></details>';}
function courses(){return heading('教程目录','从这里选择你想学的内容','第一次用 AI，可以从前五课开始。想先做 PPT、写文档，也可以直接选对应的课。')+`<section class="card core-course-banner"><h2>推荐从这几课开始</h2><div class="pill-row">${CORE_LESSONS.map(i=>button(LESSONS[i].title,'#lesson/'+i,'secondary')).join('')}</div>${button('看三个检查回答的例子','#trust/practice')}</section><div class="card"><div class="toolbar"><strong>我的学习进度</strong><span>${state.done.length} / ${LESSONS.length} 节已完成</span></div><div class="progress-track"><span style="width:${state.done.length/LESSONS.length*100}%"></span></div><p class="small-note">进度只保存在当前浏览器；换电脑、移动目录或清理浏览器后可能需要重新记录。${storageOK?'':'当前浏览器未允许保存。'}</p></div><div class="section-head"><h2>完整课程</h2><span class="tag">每次学一课就很好</span></div><div class="grid three">${COURSE_ORDER.map(i=>courseCard(LESSONS[i],i)).join('')}</div>`;}
function practice(l){switch(l.practice){
 case 'trust':case 'evidence':case 'multi':case 'retest':return `<h2>看个例子，自己检查一下</h2><p>先读材料，再看看几个 AI 分别怎么回答。你可以点开原文、重新算一算，或实际操作一下。对话是事先编好的练习内容。</p><div class="actions" style="margin-top:18px">${button('开始这次练习',l.practice==='retest'?'#verify/tool-check':l.practice==='multi'?'#verify/survey-check':'#verify/notice-check')}${button('整理我自己的提问','#trust/questions','secondary')}</div>`;
 case 'model':return `<h2>试一试：这件事需要什么能力？</h2><label class="field">选择一个任务<select id="model-task"><option value="rewrite">把通知改得亲切一些</option><option value="research">了解今天的最新信息</option><option value="website">做可勾选的离线网页</option><option value="image">解释截图里的按钮</option><option value="reason">比较有多项限制的方案</option></select></label><div class="output" id="model-result" aria-live="polite"></div>`;
 case 'prompt':return `<h2>试一试：让 AI 来问你</h2><p>这是预设的对话练习。你选择需求，观察一个模糊想法怎样逐步变清楚。</p><div id="interview" class="practice-panel"></div>`;
 case 'web':return `<h2>点一下，看网页怎样“活”起来</h2><p>同一份出行清单，逐步加上样式和交互。</p><div class="pill-row" id="web-tabs">${['只有 HTML','加上 CSS','再加 JavaScript'].map((x,i)=>`<button class="pill ${i===0?'selected':''}" data-web="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div id="web-demo"></div><p class="small-note">示例只演示本次页面内的勾选，不保存清单。</p>`;
 case 'ppt':case 'doc':return `<h2>跟着案例，走一次制作流程</h2><div class="actions" style="margin-bottom:18px">${button('打开可操作的完整演示',l.practice==='ppt'?'#demo/parents-slides':'#demo/notice')}</div><p>点击每一步查看示例成果和下一句该怎么问。下方是教学样例，并非真实 AI 生成文件。</p><div class="pill-row">${['定需求','看大纲','改小样','验收文件'].map((x,i)=>`<button class="pill ${i===0?'selected':''}" data-workflow="${i}" data-kind="${l.practice}" aria-pressed="${i===0}">${i+1}. ${x}</button>`).join('')}</div><div id="workflow-result"></div>`;
 case 'handoff':return `<h2>现在做一份交接单</h2><p>把目标、最新文件和下一步写清楚，让新对话接得住。</p><div class="actions" style="margin-top:16px">${button('打开交接单生成器','#tools/handoff')}</div>`;
 case 'help':return `<h2>把“看不懂”问具体一点</h2><p>选一个最像你现在情况的问题，复制模板就能继续问。</p><div class="pill-row">${HELP.slice(0,4).map((h,i)=>`<button class="pill" data-help="${i}">${h.name}</button>`).join('')}</div>`;
 case 'scenes':return `<h2>从你的日常开始</h2><div class="actions">${['生活','教学','办公','大学生'].map(c=>button(`${c}案例`,`#scenes/${encodeURIComponent(c)}`,'secondary')).join('')}</div>`;
 case 'stocks':return `<h2>把你的观点写成研究任务</h2><p>填写市场、日期和想法，生成带有来源要求与反证检查的提问。</p><div class="actions" style="margin-top:16px">${button('打开股票研究练习','#stocks')}</div>`;
 case 'check':case 'graduate':return `<h2>${l.practice==='check'?'分享前的四项检查':'我的作品准备好了吗？'}</h2><div class="checklist">${['我已核对关键事实、数字和来源。','我已打开实际成品，检查排版和交互。','我已检查隐私、占位文字和文件版本。','我知道如何打开、分享，以及下次如何继续。'].map(x=>`<label><input type="checkbox" data-accept>${x}</label>`).join('')}</div><p id="accept-result" class="small-note" aria-live="polite">已检查 0 / 4 项。请根据实际情况勾选。</p>`;
 default:return '';
}}
function lesson(i){const l=LESSONS[i],position=COURSE_ORDER.indexOf(i),previous=COURSE_ORDER[position-1],next=COURSE_ORDER[position+1];currentLesson=i;state.lastLesson=i;save();return `<div class="lesson-banner"><div class="eyebrow">第 ${String(COURSE_ORDER.indexOf(i)+1).padStart(2,'0')} 课 / 共 ${LESSONS.length} 课 &nbsp; · &nbsp; ${l.time} 分钟</div><h1>${l.title}</h1><p>这一课会讲：${l.goal}</p></div>${lessonOutline(l)}<div class="lesson-layout"><div class="lesson-main">${l.sections.map(([title,body],n)=>`<section class="card" id="lesson-section-${n}" tabindex="-1"><h2>${title}</h2>${body}</section>`).join('')}<section class="card" id="lesson-practice" tabindex="-1">${practice(l)}</section><section class="card"><h2>你可以这样问</h2>${template(l.prompt)}<p class="small-note">把方括号里的内容换成自己的信息，再发给你使用的 AI。</p></section><section class="card quiz" id="lesson-quiz" tabindex="-1"><div class="quiz-label">随堂练习 · 选一个答案</div><h3>${l.quiz.q}</h3><div class="quiz-options">${l.quiz.options.map((o,j)=>`<button class="quiz-option" data-answer="${j}" aria-pressed="false">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}</div><div class="feedback" id="quiz-feedback" role="status"></div></section><div class="card strip"><span class="strip-icon">?</span><div><strong>这一课还有不懂的地方？</strong><p>把不懂的原话交给 AI，请它换个例子，一步一步解释。</p></div><button class="btn secondary" data-help="0">看看怎么问</button></div><div class="lesson-finish">${button(previous===undefined?'返回课程':'上一课',previous===undefined?'#courses':`#lesson/${previous}`,'secondary')}<button class="btn" id="complete-lesson" ${state.done.includes(i)?'':'disabled'}>${state.done.includes(i)?(next===undefined?'回顾全部课程':'继续下一课'):'答对随堂题，再标记学完'}</button></div><p class="small-note"><a href="#sources">查看官方资料与说明</a></p></div><aside class="lesson-sidebar"><strong>学习路线</strong>${COURSE_ORDER.map(n=>`<a class="${n===i?'current':''}" href="#lesson/${n}">${state.done.includes(n)?'✓':String(COURSE_ORDER.indexOf(n)+1).padStart(2,'0')} &nbsp; ${LESSONS[n].title}</a>`).join('')}<div class="progress-track"><span style="width:${state.done.length/LESSONS.length*100}%"></span></div><p class="small-note">${state.done.length} / ${LESSONS.length} 节已完成</p></aside></div>`;}
let sceneCategory='全部', sceneQuery='';
function sceneCard(s){return `<article class="card scene-card"><div class="toolbar"><span class="scene-kind">${s.category}</span><span class="badge">${s.format}</span></div><h3>${s.title}</h3><p>${s.desc}</p><button class="btn secondary" data-scene="${s.id}">查看提问模板</button></article>`;}
function scenes(category){sceneCategory=['生活','教学','办公','大学生','股票研究','PPT','文档'].includes(category)?category:'全部';sceneQuery='';return heading('常用提问',`${SCENES.length} 个备用提问模板`,'这里是模板速查。想看材料、初稿、修改和成品，请到案例演示。')+button('回到完整案例演示','#scenes','secondary')+`<div class="toolbar"><div class="pill-row" id="scene-filters">${['全部','生活','教学','办公','大学生','PPT','文档','股票研究'].map(x=>`<button class="pill ${x===sceneCategory?'selected':''}" data-filter="${x}" aria-pressed="${x===sceneCategory}">${x}</button>`).join('')}</div><label><span class="hidden">搜索案例</span><input class="search" id="scene-search" type="search" aria-label="搜索案例" placeholder="搜索：家长会、通知、股票…"></label></div><p id="scene-count" class="small-note" aria-live="polite"></p><div class="grid three" id="scene-results" style="margin-top:18px"></div>`;}
function updateScenes(){const list=SCENES.filter(s=>(sceneCategory==='全部'||s.category===sceneCategory||s.format===sceneCategory)&&`${s.title}${s.desc}${s.prompt}${s.category}${s.format}`.toLowerCase().includes(sceneQuery.toLowerCase()));$('#scene-results').innerHTML=list.map(sceneCard).join('')||'<div class="card empty"><h3>暂时没有这个案例</h3><p>试试更短的关键词，或切回“全部”。</p></div>';$('#scene-count').textContent=`找到 ${list.length} 个模板`;}
function field(label,name,placeholder,area=false,value=''){return `<label class="field">${label}${area?`<textarea name="${name}" placeholder="${placeholder}">${esc(value)}</textarea>`:`<input name="${name}" placeholder="${placeholder}" value="${esc(value)}">`}</label>`;}
function outputBox(){return `<div id="generated-panel" class="hidden"><h3 style="margin-top:24px">可以把下面这段话发给 AI</h3><div id="generated-output" class="output" aria-live="polite"></div><div class="actions"><button class="btn" data-copy-output>复制到 AI 中使用</button><button class="btn secondary" data-download-output>保存为文本</button></div><p class="small-note">这是按你填写的内容拼成的提问，尚未发送给任何 AI。请检查并替换未填写的占位项。</p></div>`;}
function toolsPage(mode){const handoff=mode==='handoff';return heading('提问工具箱','不知道怎么开口？先填几句话。','不用想好所有细节，知道多少就先填多少。这里会帮你整理成一段提问，你再复制给平时用的 AI。填写的内容只留在这个页面。')+`<div class="pill-row">${button('提问生成器','#tools',handoff?'secondary':'')}${button('新对话交接单','#tools/handoff',handoff?'':'secondary')}</div><section class="card"><h2>${handoff?'换个对话时，把这些信息带过去':'把你想做的事告诉 AI'}</h2><form id="builder" data-mode="${handoff?'handoff':'prompt'}" style="margin-top:22px">${handoff?`
 ${field('这件事最终要做成什么？','goal','例如：三年级阅读家长会，8 页 PPT')}<div class="form-grid">${field('已经确认的要求','constraints','例如：20 分钟、蓝白配色、大字号',true)}${field('已经做完的内容','done','例如：大纲和前 6 页已确认',true)}</div>${field('最新文件、版本与用途','files','例如：家长会_v2.pptx；需要重新附上实际文件',true)}<div class="form-grid">${field('未解决问题、尝试过的办法','issues','例如：第 7 页内容太多，缩小字号后仍难读',true)}${field('下一步与待确认事项','next','例如：仅拆分第 7 页；日期还需学校确认',true)}</div>`:`
 ${field('你想完成什么？','goal','例如：做一份阅读主题家长会 PPT')}<div class="form-grid">${field('给谁用？','audience','例如：三年级学生家长')}${field('希望做成什么格式？','format','例如：8 页、可编辑的 .pptx')}</div>${field('你有哪些材料？','materials','例如：活动安排和脱敏的阅读记录；没有也可以写“暂无”',true)}${field('有哪些要求与限制？','constraints','例如：20 分钟；用大白话；缺数据不能编造',true)}<label class="field">开始前怎么做？<select name="approach"><option>先复述理解，缺信息时反问；给一个小样让我确认</option><option>我还没想清楚，请一次问我一个问题</option><option>要求已经明确，请制作初稿并列出未确认事项</option></select></label>`}<button type="submit" class="btn">${handoff?'生成交接单':'整理成一段提问'}</button><p class="small-note">不要填写密码、身份证号、学生实名或账户凭证。离开此页会清空表单，请先复制或保存。</p></form>${outputBox()}</section><div class="section-head"><h2>还不知道怎么说？</h2></div><div class="grid two">${HELP.slice(0,4).map((h,i)=>`<div class="card"><h3>${h.name}</h3><p>${h.text.slice(0,55)}…</p><button class="btn secondary" style="margin-top:16px" data-help="${i}">查看求助模板</button></div>`).join('')}</div>`;}
function helpPage(){return heading('遇到问题时','AI 说的没看懂，怎么继续问？','直接告诉 AI：“这段我没懂，请换个说法。”选一个你遇到的情况，把模板复制回原对话。')+`<div class="hero" style="margin-bottom:25px"><div><div class="eyebrow">记住这四句话</div><h2>先说想做什么，<br>再说哪一步没弄懂。</h2><p>告诉它目标、已经做的步骤、实际看到的画面和预期结果。请它一次只给一步，等你操作后再继续。</p></div><div class="demo-chat"><div class="chat-top">跟着问，就能接着学 <span>教学示例</span></div><div class="bubble user">什么叫“解压”？我不会。</div><div class="bubble">压缩包像一个装着文件的袋子，解压就是取出里面的文件。你用的是 Windows 电脑吗？</div><div class="bubble user">是，先告诉我第一步点哪里。</div></div></div><div class="grid two">${HELP.map((h,i)=>`<section class="card"><span class="badge">求助 ${String(i+1).padStart(2,'0')}</span><h3 style="margin-top:12px">${h.name}</h3>${template(h.text)}</section>`).join('')}</div><div class="section-head"><h2>常见卡点</h2></div>${[
 ['网页打开后只有文字怎么办？','问 AI：“我已解压，打开 index.html 只看到文字。请检查 styles.css、app.js、data.js 是否和它在同一文件夹，是否错误改了文件后缀。一次只教我检查一项。”'],
 ['AI 只给大纲，没有 PPT 或 Word 文件？','问 AI：“你现在能生成可下载的 .pptx / .docx 吗？可以的话请交付文件；不能的话请明确说明，并给我复制内容到办公软件、保存成文件的步骤。”'],
 ['复制按钮没有反应？','部分本地浏览器会限制剪贴板。页面会提供手动复制窗口；选中文本，Windows 按 Ctrl+C，Mac 按 Command+C，然后到 AI 对话里粘贴。'],
 ['它一直重复错误的方法？','问 AI：“请停止重复。列出你已尝试的方法、为什么没解决、还缺什么信息，再给一个不同的、可撤销的排查步骤。”'],
 ['我不认识股票指标怎么办？','问 AI：“请先只解释这一个指标，用虚构数字举例并明确标注，再让我复述。说明它有哪些局限，不要直接跳到推荐股票。”']
 ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}`;}
function stocksPage(){return heading('股票研究入门','想让 AI 帮你研究股票，可以怎么问？','比如你看好一个行业，或者想弄懂一家公司的财报，都可以先写下理由。我们来看看怎样问，怎样查资料。这里不提供实时行情，也不替你买卖股票。')+`<div class="callout warn">用于学习研究方法，不构成个性化投资建议。真实投资可能亏损；重要判断应核对正式披露，不能仅依据 AI 输出。</div><div class="grid two"><section class="card"><div class="eyebrow">第一步：说说你的想法</div><h2>把观点交给 AI 之前</h2><form id="stock-form" style="margin-top:20px"><label class="field">研究方式<select name="type"><option>把我的想法转成选股条件</option><option>分析一只股票</option><option>比较两家公司</option><option>对我的观点做反方检查</option></select></label><div class="form-grid"><label class="field">市场<select name="market"><option>A 股</option><option>港股</option><option>美股</option><option>尚未确定，请先反问我</option></select></label><label class="field">数据截止日期<input name="date" type="date" required></label></div>${field('公司全名、代码，或要研究的行业','target','例如：行业名称；个股请写公司全名和股票代码')}${field('你的想法和理由','idea','例如：我关注分红持续性，但不懂怎样判断',true)}${field('你已经有的材料或条件（选填）','material','例如：公司年报；只看主营业务明确的企业',true)}<button class="btn" type="submit">生成股票研究提问</button></form></section><section class="card"><div class="eyebrow">第二步：接着往下问</div><h2>“分红稳定”，可以怎么研究？</h2><p>下面是方法示例，没有对应真实证券，也没有推荐阈值。</p><ol class="number-steps"><li><b>把词语讲清</b>请解释股息率和分红率有什么区别，用虚构数字举例。</li><li><b>把条件讲清</b>“稳定”指连续分红、金额波动，还是现金流覆盖？先问我选哪种定义。</li><li><b>把数据对齐</b>注明价格日期、分红所属年度、是否含特别分红，以及币种。</li><li><b>把反例找出来</b>高股息是否因为股价下跌？分红是否超过持续产生的现金？</li></ol><div class="actions">${button('学习完整股票研究课','#lesson/9','secondary')}<button class="btn soft" data-help="0">指标看不懂？</button></div></section></div><section id="stock-output-wrap" class="card hidden" style="margin-top:22px">${outputBox()}</section><div class="section-head"><h2>先看一个完整演示</h2></div><div class="grid two">${demoCard(DEMOS.find(d=>d.slug==='stock-evidence'))}</div><div class="section-head"><h2>六个股票研究提问模板</h2><a href="#sources">查找官方披露入口</a></div><div class="grid three">${SCENES.filter(s=>s.category==='股票研究').map(sceneCard).join('')}</div><div class="card" style="margin-top:22px"><h2>拿到 AI 分析后，再问这一句</h2>${template('请把刚才的分析分成“已核实事实、推断、情景假设、数据缺失”四类。每项事实列来源与日期；指出最强的反对证据，以及什么变化会推翻结论。不要为了迎合我的观点而省略风险。')}</div>`;}
function sourcesPage(){return heading('关于这份教程','资料与使用说明','教学内容整理于 2026 年 10 月 1 日。产品功能、入口、模型与套餐会变化，以官方说明和你实际看到的界面为准。')+`<section class="card"><h2>官方资料入口</h2><p>这里介绍的是提问和检查的方法，不能保证 AI 每次都正确。即使几个 AI 都同意，重要的事情也要回到原文或实际操作中核对。</p><ul class="source-list"><li><a href="https://www.anthropic.com/research/towards-understanding-sycophancy-in-language-models" target="_blank" rel="noopener noreferrer">Anthropic：语言模型迎合行为研究</a>：研究讨论了模型赞同用户观点的倾向；不能把赞同当作事实核实。</li><li><a href="https://learn.chatgpt.com/docs/quickstart" target="_blank" rel="noopener noreferrer">OpenAI 官方入门文档</a>：产品入口和开始使用；原 Codex 入门地址现跳转到此处。</li><li><a href="https://learn.chatgpt.com/docs/prompting" target="_blank" rel="noopener noreferrer">OpenAI 官方提问指南</a>：目标、背景、成品格式与边界。</li><li><a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noopener noreferrer">腾讯云 WorkBuddy 官方产品页</a>：自然语言办公任务与本地文件工作。</li><li><a href="https://www.doubao.com/download/desktop" target="_blank" rel="noopener noreferrer">豆包桌面版官方页面</a>：截图问答、阅读与创作等能力。本站不是独立“豆包办公”产品的官方教程。</li><li><a href="https://www.sse.com.cn/disclosure/listedinfo/announcement/" target="_blank" rel="noopener noreferrer">上海证券交易所上市公司公告</a>、<a href="https://www.szse.cn/disclosure/listed/notice/" target="_blank" rel="noopener noreferrer">深圳证券交易所上市公司公告</a>：查找正式披露，注意市场、代码和报告期。</li><li><a href="https://www.hkexnews.hk/index_c.htm" target="_blank" rel="noopener noreferrer">香港交易所披露易</a>、<a href="https://www.sec.gov/edgar/search/" target="_blank" rel="noopener noreferrer">美国 SEC EDGAR</a>：港股、美股研究可从正式披露开始。</li><li><a href="https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-alerts/artificial-intelligence-fraud" target="_blank" rel="noopener noreferrer">Investor.gov：AI 与投资欺诈提醒</a>：警惕以 AI 名义承诺高收益的宣传。</li></ul><p class="small-note">外部资料需要联网。它们支持产品概述与来源核查方法；课程练习、案例模板和流程是本站编写的教学建议，不代表厂商承诺。</p></section><section class="card" style="margin-top:22px"><h2>怎样打开和分享</h2><ol class="number-steps"><li><b>打开本地网站，或完整解压收到的 ZIP</b>不要只在压缩包预览里打开网页。</li><li><b>双击 index.html</b>使用现代 Edge、Chrome、Firefox 或 Safari。无需安装依赖、注册或输入 API 密钥。</li><li><b>保持文件放在一起</b>保留整个网站文件夹，包含 index.html、三份 CSS 与七份 JS 文件；缺失文件会导致页面异常。手机浏览器是否允许打开本地多文件网页取决于系统；首次学习推荐电脑。</li><li><b>分享整个压缩包</b>模板和练习离线可用；访问官方产品和使用真实 AI 时需要相应网络与账号。</li></ol></section><section class="card" style="margin-top:22px"><h2>填写的内容保存在哪里？练习会连接 AI 吗？</h2><p>本站不连接 AI、不读取电脑文件、不上传表单、不使用统计跟踪。课程完成状态、上次阅读的课程和字号偏好尝试保存在当前浏览器。表单输入仅用于本地拼接提问，刷新或离开后不保留；导出的文本由你自行保管。</p><p>案例中的材料、对话、数据、研究片段和成品均为人工编写的虚构教学样例，不是产品录屏或真实资料。可下载的 HTML 是静态阅读版。真实 .pptx、.docx 和股票分析，需要把提问复制到有相应能力的 AI 产品中完成并验收。</p><button class="btn secondary" id="reset-progress" style="margin-top:18px">重置学习进度</button></section>`;}
function route(){const parts=location.hash.slice(1).split('/');const page=parts[0]||'home';let arg='';try{arg=decodeURIComponent(parts[1]||'');}catch{}currentLesson=null;const active=page==='verify'?'trust':page==='lesson'?'courses':(page==='demo'||page==='templates'?'scenes':page);$('#navigation').innerHTML=nav.map(([key,icon,label])=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${key==='courses'?`<span class="nav-count">${LESSONS.length}</span>`:''}</a>`).join('');let html,title;
 if(page==='lesson' && /^\d+$/.test(arg) && LESSONS[Number(arg)]){html=lesson(Number(arg));title=LESSONS[Number(arg)].title;}
 else if(page==='courses'){html=courses();title='全部课程';}
 else if(page==='trust'){html=trustPage();title='怎样放心用 AI';}
 else if(page==='verify'){html=verificationPage(arg);title='多 AI 验证实验';}
 else if(page==='scenes'){html=demosPage(arg);title='案例演示';}
 else if(page==='templates'){html=scenes(arg);title='提问模板速查';}
 else if(page==='demo'){html=demoPage(arg);title='完整案例演示';}
 else if(page==='students'){html=studentsPage();title='大学生专区';}
 else if(page==='tools'){html=toolsPage(arg);title='提问工具箱';}
 else if(page==='help'){html=helpPage();title='看不懂？问 AI';}
 else if(page==='stocks'){html=stocksPage();title='股票研究';}
 else if(page==='sources'){html=sourcesPage();title='资料与使用说明';}
 else if(page==='about'){html=aboutPage();title='网站制作过程';}
 else if(page==='home'){html=home();title='学习首页';}
 else{html=heading('没有找到页面','这个地址好像不对。','可以回到首页，或者从目录重新选一课。')+button('回到首页','#home');title='没有找到页面';}
 closeMenu();main.innerHTML=html;$('#breadcrumb').textContent=title;document.title=`${title} · AI 生活课堂`;if($('#detail-dialog').open)$('#detail-dialog').close();initPage();window.scrollTo(0,0);main.focus({preventScroll:true});if(page==='trust'){const section={practice:'trust-practice',questions:'trust-questions'}[arg];if(section){const target=document.getElementById(section);target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({block:'start'});}}}
function modal(html){$('#dialog-body').innerHTML=html;$('#detail-dialog').showModal();}
$('.dialog-close').onclick=()=>$('#detail-dialog').close();
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
async function copy(text){try{if(!navigator.clipboard)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(text);toast('已复制。到你使用的 AI 对话里粘贴即可。');}catch{modal(`<h2 id="dialog-title">请手动复制这段文字</h2><p>当前浏览器限制了自动复制。选中文字，按 Ctrl+C（Mac 为 Command+C）。</p><label class="field">要复制的内容<textarea id="manual-copy" rows="9">${esc(text)}</textarea></label>`);$('#manual-copy').focus();$('#manual-copy').select();}}
function download(text){const blob=new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='AI课堂-我的提问.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已准备文本文件，请查看浏览器下载。');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.jump){const target=document.getElementById(b.dataset.jump);if(target){target.focus({preventScroll:true});target.scrollIntoView({block:'start'});}}
 if(b.hasAttribute('data-copy-parent'))copy($('pre',b.closest('.template')).textContent);
 if(b.hasAttribute('data-copy-output'))copy($('#generated-output').textContent);
 if(b.hasAttribute('data-download-output'))download($('#generated-output').textContent);
 if(b.dataset.help!==undefined){const h=HELP[Number(b.dataset.help)];modal(`<span class="badge">让 AI 接着教你</span><h2 id="dialog-title">${h.name}</h2><p>替换方括号内的信息，复制回你使用的 AI 对话。</p>${template(h.text)}`);}
 if(b.dataset.scene!==undefined){const s=SCENES.find(x=>x.id===Number(b.dataset.scene));modal(`<span class="badge">${s.category} · ${s.format}</span><h2 id="dialog-title">${s.title}</h2><p>${s.desc}</p>${template(s.prompt)}<div class="callout"><strong>成品怎样才算合格？</strong><br>${s.check}</div><p class="small-note">看不懂时继续问：“请用大白话解释，一次只教我一步，等我回复后继续。”</p>`);}
 if(b.dataset.filter!==undefined){sceneCategory=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});updateScenes();}
 if(b.dataset.answer!==undefined && currentLesson!==null){const l=LESSONS[currentLesson],correct=Number(b.dataset.answer)===l.quiz.answer;$$('[data-answer]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#quiz-feedback').className=`feedback ${correct?'correct':'incorrect'}`;$('#quiz-feedback').textContent=(correct?'答对了。':'再想一想。')+l.quiz.explain;if(correct){$('#complete-lesson').disabled=false;$('#complete-lesson').textContent=state.done.includes(currentLesson)?'继续学习':'标记学完，继续学习';}}
 if(b.dataset.web!==undefined)webDemo(Number(b.dataset.web));
 if(b.dataset.workflow!==undefined)workflow(b.dataset.kind,Number(b.dataset.workflow));
 if(b.id==='reset-progress')modal('<h2 id="dialog-title">重置学习进度？</h2><p>这会清除本浏览器内的课程完成记录，已下载文件不会受影响。</p><div class="actions" style="margin-top:20px"><button class="btn" id="confirm-reset">确认重置</button><button class="btn secondary" id="cancel-reset">保留进度</button></div>');
 if(b.id==='cancel-reset')$('#detail-dialog').close();
 if(b.id==='confirm-reset'){state.done=[];state.lastLesson=null;save();$('#detail-dialog').close();route();toast('学习进度已重置。');}
});
function showOutput(text){$('#generated-panel').classList.remove('hidden');$('#generated-output').textContent=text;$('#generated-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}
function initPage(){
 initTrust();
 if($('#demo-results'))updateDemos();
 if($('#demo-stage'))showDemoStep();
 if($('#scene-results')){updateScenes();$('#scene-search').addEventListener('input',e=>{sceneQuery=e.target.value.trim();updateScenes();});}
 if($('#model-task')){const results={rewrite:'先用默认或快速模式做一个短草稿。重点看语气、长度和事实是否符合要求，不必先升级模型。',research:'优先确认联网或实时资料工具可用。要求来源、更新时间，点开核实。更强的模型不能替代最新资料。',website:'选择能编写、保存文件并检查网页的工具环境。先做一个按钮可用的小样，再检查离线打开。',image:'先确认支持上传图片。遮住隐私后提供截图，并要求它只根据可见内容说明；看不清就反问。',reason:'可以尝试更强的思考模式。把约束与优先级写清楚，要求给出取舍依据和待确认事项。'};const update=()=>$('#model-result').textContent=results[$('#model-task').value];$('#model-task').onchange=update;update();}
 if($('#interview'))interview(0);
 if($('#web-demo'))webDemo(0);
 if($('#workflow-result'))workflow(LESSONS[currentLesson].practice,0);
 $$('[data-accept]').forEach(x=>x.onchange=()=>$('#accept-result').textContent=`已检查 ${$$('[data-accept]:checked').length} / 4 项。${$$('[data-accept]:checked').length===4?'很好，再实际打开成品确认一次。':'请根据实际情况勾选。'}`);
 if($('#complete-lesson'))$('#complete-lesson').onclick=()=>{if(!state.done.includes(currentLesson))state.done.push(currentLesson);save();const next=COURSE_ORDER[COURSE_ORDER.indexOf(currentLesson)+1];location.hash=next===undefined?'courses':`lesson/${next}`;toast('这一课已记录完成。');};
 if($('#builder'))$('#builder').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,d=new FormData(form);const v=(k,p)=>String(d.get(k)||'').trim()||`[请补充：${p}]`;const handoff=form.dataset.mode==='handoff';showOutput(handoff?`请接手这个任务，先复述目标，检查缺失的附件和权限；不确定时先问我，不要重新做已确认的部分。\n\n目标：${v('goal','最终目标')}\n已确认要求：${v('constraints','要求与边界')}\n已完成：${v('done','完成内容')}\n最新文件与版本：${v('files','实际文件名与用途，请重新附上')}\n未解决问题及尝试：${v('issues','问题与尝试')}\n下一步与待确认事项：${v('next','下一步')}\n\n请区分已确认事实、假设和待确认事项。若读不到文件，先告诉我需要补什么。`:`我想完成：${v('goal','目标')}。\n使用对象：${v('audience','给谁用')}。\n现有材料：${v('materials','材料或暂无')}。\n成品格式：${v('format','成品形式')}。\n要求与限制：${v('constraints','字数、时间、风格或边界')}。\n\n${v('approach','如何开始')}。\n请用日常语言解释，未知信息不要编造；如果无法生成实际文件，请明确说明。完成后说明如何打开、检查了什么以及哪些地方尚未验证。`);};
 if($('#stock-form'))$('#stock-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget);const v=(k,p)=>String(d.get(k)||'').trim()||`[请补充：${p}]`;$('#stock-output-wrap').classList.remove('hidden');showOutput(`请帮助我做股票研究，研究方式：${v('type','方式')}。\n市场：${v('market','市场')}。\n数据截止日期：${v('date','日期')}。\n研究对象：${v('target','公司全名和代码，或行业')}。\n我的想法及理由：${v('idea','观点')}。\n已有材料与条件：${v('material','材料或暂无')}。\n\n1. 先复述我的想法，核对市场、公司与代码；缺信息就一次问一个问题。\n2. 解释必要的指标，再把想法转成可验证条件。不要擅自设筛选阈值或迎合我的结论。\n3. 优先用交易所公告、公司财报，标注报告期、发布日期、链接、页码、单位与口径。无法联网或缺数据时明确说明，不编造行情。\n4. 分开列出已核实事实、推断、情景假设、数据缺失；比较时统一时期、币种与会计口径。\n5. 同时列支持证据与最强反对证据，指出会推翻判断的事件。\n6. 不承诺收益，不用未经核实的目标价替代分析。最后给出待核查问题和来源清单。\n\n我如果看不懂，请用日常语言和明确标为虚构的数字举例，一次解释一个概念。`);};
}
function interview(step,answer=''){const panel=$('#interview');if(step===0){panel.innerHTML='<div class="bubble">你最想先做什么？</div><div class="pill-row"><button class="pill" data-interview="家长会 PPT">家长会 PPT</button><button class="pill" data-interview="家庭出行清单">家庭出行清单</button><button class="pill" data-interview="活动通知">活动通知</button></div>';$$('[data-interview]',panel).forEach(b=>b.onclick=()=>interview(1,b.dataset.interview));}else if(step===1){panel.innerHTML=`<div class="bubble user">我想做${answer}。</div><div class="bubble">好的。你希望怎样使用它？</div><div class="pill-row"><button class="pill" id="interview-one">给大家一起看和讲</button><button class="pill" id="interview-two">发给别人自己阅读</button></div>`;$('#interview-one').onclick=()=>interview(2,`${answer}，用于现场讲解`);$('#interview-two').onclick=()=>interview(2,`${answer}，用于别人自行阅读`);}else{panel.innerHTML=`<div class="bubble">目前已知道：${answer}。接下来还应确认对象、时长、材料和成品格式。</div>${template(`我想制作${answer}。请继续一次问我一个问题，先确认使用对象，再问材料与成品要求。最后复述完整需求，等我确认。`)}<button class="quiet" id="restart-interview">重新练一次</button>`;$('#restart-interview').onclick=()=>interview(0);}}
function webDemo(stage){$$('[data-web]').forEach(b=>{const yes=Number(b.dataset.web)===stage;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});$('#web-demo').innerHTML=`<p>${['HTML：先把内容放上来。有标题和清单，但这里还没有勾选功能。','CSS：加上颜色、留白和清晰的排版。样式改变了，操作逻辑还没加入。','JavaScript：现在试着勾选，完成数量会跟着变化。'][stage]}</p><div class="demo-output ${stage>0?'styled':''}"><h3>周末出行清单</h3>${['带好证件','准备充电器','带上雨伞'].map(x=>`<label>${stage===2?'<input type="checkbox" data-demo-check>':'<span aria-hidden="true">□ &nbsp;</span>'}${x}</label>`).join('')}${stage===2?'<div id="demo-count" class="mini-result" role="status">已准备 0 / 3 件</div>':''}</div>`;$$('[data-demo-check]').forEach(b=>b.onchange=()=>$('#demo-count').textContent=`已准备 ${$$('[data-demo-check]:checked').length} / 3 件`);}
function workflow(kind,step){$$('[data-workflow]').forEach(b=>{const yes=Number(b.dataset.workflow)===step;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});const ppt=[['先说给谁讲、讲多久','三年级家长会 · 阅读习惯 · 20 分钟 · 8 页。听完后，家长能选一种方法和孩子练一周。','请先问清我手头有哪些可靠材料，不要虚构班级数据。'],['逐页检查逻辑','① 今天的目标\n② 我们观察到的阅读问题（待补材料）\n③ 固定阅读时间\n④ 让孩子自己选书\n⑤ 用问题交流，不考记忆\n⑥ 一个家庭示例\n⑦ 一周行动清单\n⑧ 总结与沟通','请给每页安排讲述时间，检查总计是否约 20 分钟。'],['具体说出哪里要改','小样问题：内容页用了 6 段长文。\n修改目标：保留 3 个重点，每点不超过 20 字；补充讲解放进备注。','请保留封面，只修改第 2 页。正文按投影阅读放大，先给我看这一页。'],['拿到文件再检查','□ 确实有 .pptx 文件\n□ 文字可以编辑\n□ 播放没有溢出或遮挡\n□ 数字和引用已核实\n□ 试讲时间合适\n□ PDF 备用版与源文件一致','请交付可编辑 PPT 和检查记录。没有实际检查过的项目写“未验证”。']];const doc=[['先列出已知信息','活动：班级阅读分享\n对象：三年级家长\n时间：待确认\n地点：待确认\n准备：带一本愿意分享的书','请先列出缺失信息；未知的日期和地点不要自行填写。'],['确认一页的结构','标题：阅读分享活动通知\n第一段：活动目的\n第二部分：时间、地点、对象\n第三部分：准备事项\n末尾：联系人与落款（待确认）','请先给正文草稿，正式安排尚未确认的地方统一标注“待确认”。'],['把长句改成易读信息','原句：请各位家长在活动开始前携带所需要的各类相关材料准时参加。\n改为：请带一本愿意分享的书，按已确认的活动时间参加。\n如果时间尚未确定，就标记“待确认”，不要另加提前到场的要求。','请把准备事项改成短清单，保留原事实，不增加未确认安排。'],['打开真实成品','□ Word 中可编辑\n□ 日期、地点已确认\n□ A4 打印预览是一页\n□ 表格没有截断\n□ PDF 与 Word 内容一致\n□ 正式发送前清除待确认项','请生成 .docx 和 PDF。说明哪些事实还需我确认，不要提前替我发送。']];const row=(kind==='ppt'?ppt:doc)[step];$('#workflow-result').innerHTML=`<div class="practice-panel"><h3>${row[0]}</h3><div class="output">${esc(row[1])}</div>${template(row[2],'下一句可以这样问')}</div>`;}
window.addEventListener('hashchange',route);
route();
